package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.File;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Date;
import java.util.List;
import java.util.zip.ZipException;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ZipArchiveEntry#isUnixSymlink
 */
public class ZipArchiveEntry_isUnixSymlink_TriageGen1Test {

    @Test
    public void testIsUnixSymlink_FalseWhenModeIsZero() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        entry.setUnixMode(0);
        assertFalse("Should return false when Unix mode is 0", entry.isUnixSymlink());
    }

    @Test
    public void testIsUnixSymlink_FalseWhenLinkFlagIsNotSet() {
        // Using a common Unix mode like directory (040000) which does not include LINK_FLAG
        // Assuming UnixStat.LINK_FLAG is a specific bit mask.
        // We pick a value that is definitely not the LINK_FLAG.
        int modeWithoutLinkFlag = 0755; 
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        entry.setUnixMode(modeWithoutLinkFlag);

        // Ensure we aren't accidentally passing by coincidence
        if ((modeWithoutLinkFlag & UnixStat.LINK_FLAG) != UnixStat.LINK_FLAG) {
            assertFalse("Should return false when LINK_FLAG bit is not set", entry.isUnixSymlink());
        } else {
            fail("Test setup error: modeWithoutLinkFlag actually contains LINK_FLAG");
        }
    }

    @Test
    public void testIsUnixSymlink_TrueWhenLinkFlagIsSet() {
        // Set the mode to exactly the LINK_FLAG or LINK_FLAG combined with other bits
        int modeWithLinkFlag = UnixStat.LINK_FLAG | 0755;
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        entry.setUnixMode(modeWithLinkFlag);
        assertTrue("Should return true when LINK_FLAG bit is set", entry.isUnixSymlink());
    }

    @Test
    public void testIsUnixSymlink_TrueWhenOnlyLinkFlagIsSet() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        entry.setUnixMode(UnixStat.LINK_FLAG);
        assertTrue("Should return true when only LINK_FLAG is set", entry.isUnixSymlink());
    }
}
